-- ADCS actuators and sensors from NASA S3VI State-of-the-Art 2026 (NASA/TP-20260003140),
-- Tables 5-3 to 5-9; reviewed 2026-10-30. No prices or numerical TRL inferred.
-- Skipped: units over ~2 kg; rows with misaligned columns (NewSpace NRWA wheels, Trillian-1,
-- Space Inventor MIST and IMU-P4); Space Inventor listings that duplicate VEOWARE wheels and
-- Jena-Optronik ASTRO CL; NovAtel OEM-IMU-STIM300 (repackaged Safran STIM300); CubeWheel CW0017,
-- which is existing row 54; accelerometer-only and spin-stabilized-only sensors.

INSERT INTO subsystem VALUES
 ('reaction_wheel', 'hardware','Reaction wheel', 'Momentum storage per kg','mNms/kg', 1),
 ('magnetorquer',   'hardware','Magnetorquer',   'Dipole per watt',        'Am2/W',   1),
 ('star_tracker',   'hardware','Star tracker',   'Cross-axis accuracy',    'arcsec',  0),
 ('sun_sensor',     'hardware','Sun sensor',     'Accuracy (3-sigma)',     'deg',     0),
 ('horizon_sensor', 'hardware','Horizon sensor', 'Accuracy',               'deg',     0),
 ('magnetometer',   'hardware','Magnetometer',   'Resolution',             'nT',      0),
 ('gyro',           'hardware','Gyro / IMU',     'Gyro bias stability',    'deg/hr',  0);

-- Existing CubeSpace wheels move to the new subsystem. Row 54 is the CW0017: record NASA's peak power.
UPDATE component SET subsystem = 'reaction_wheel' WHERE id IN (54, 55);
UPDATE component SET power_w = 0.85, efficiency = 28.33, efficiency_basis = 'literature',
  notes = notes || ' Matches CubeWheel CW0017 in NASA SoA 2026 Table 5-3: peak power 0.85 W (average <0.142 W), momentum 0.0017 Nms. Power is now peak, consistent with other wheels.'
  WHERE id = 54;
UPDATE component SET notes = notes || ' Power is average, not peak (no peak figure found).' WHERE id = 55;

